797:     @Bean
798:     org.springframework.boot.web.servlet.FilterRegistrationBean<jakarta.servlet.Filter>
799:         observedReportCapture() {
800:       jakarta.servlet.Filter filter =
801:           (request, response, chain) -> {
802:             var http = (jakarta.servlet.http.HttpServletRequest) request;
803:             UUID p3Execution =
804:                 P3_EXECUTIONS.stream()
805:                     .filter(
806:                         id ->
807:                             http.getRequestURI()
808:                                 .equals("/internal/studio/executions/" + id + "/progress"))
809:                     .findFirst()
810:                     .orElse(null);
811:             if (p3Execution != null) {
812:               var wrapped =
813:                   new org.springframework.web.util.ContentCachingRequestWrapper(http, 262144);
814:               chain.doFilter(wrapped, response);
815:               if (((jakarta.servlet.http.HttpServletResponse) response).getStatus() >= 200
816:                   && ((jakarta.servlet.http.HttpServletResponse) response).getStatus() < 300
817:                   && wrapped.getContentAsByteArray().length > 0) {
818:                 p3CaptureOrdinaryReport(p3Execution, wrapped.getContentAsByteArray());
819:               }
820:               return;
821:             }
822:             UUID target = preReadyId;
823:             boolean capture =
824:                 target != null
825:                     && http.getRequestURI()
826:                         .equals("/internal/studio/executions/" + target + "/progress")
827:                     && http.getHeader("X-Observed-Negative-Probe") == null;
828:             if (!capture) {
829:               chain.doFilter(request, response);
830:               return;
831:             }
832:             if (HOLD_TERMINAL_RETRY.get() && TERMINAL_ROLLBACKS.get() > 0) {
833:               retryPaused.countDown();
834:               try {
835:                 if (!retryRelease.await(10, java.util.concurrent.TimeUnit.SECONDS)) {
836:                   throw new jakarta.servlet.ServletException("Controlled retry barrier timed out");
837:                 }
838:               } catch (InterruptedException interrupted) {
839:                 Thread.currentThread().interrupt();
840:                 throw new jakarta.servlet.ServletException("Controlled retry barrier interrupted");
841:               }
842:             }
843:             var wrapped =
844:                 new org.springframework.web.util.ContentCachingRequestWrapper(http, 262144);
845:             try {
846:               chain.doFilter(wrapped, response);
847:             } finally {
848:               if (wrapped.getContentAsByteArray().length > 0) {
849:                 try {
850:                   RECEIVED_FAILURE_REPORTS.add(C.parseWire(wrapped.getContentAsByteArray()));
851:                 } catch (RuntimeException invalid) {
852:                   /* Original production parsing still owns the response. */
853:                 }
854:               }
855:             }
856:           };
857:       var registration = new org.springframework.boot.web.servlet.FilterRegistrationBean<>(filter);
858:       registration.addUrlPatterns("/internal/studio/executions/*");
859:       return registration;
860:     }
