4034:   private static void p3CaptureOrdinaryReport(UUID execution, byte[] bytes) {
4035:     int phase = 1;
4036:     try {
4037:       if (bytes.length > 262144) {
4038:         throw new IllegalArgumentException("P3 callback witness bound");
4039:       }
4040:       String text = StandardCharsets.UTF_8.newDecoder()
4041:           .onMalformedInput(java.nio.charset.CodingErrorAction.REPORT)
4042:           .onUnmappableCharacter(java.nio.charset.CodingErrorAction.REPORT)
4043:           .decode(java.nio.ByteBuffer.wrap(bytes)).toString();
4044:       phase = 2;
4045:       // Strict duplicates/trailing tokens remain; ordinary timing numbers are not canonical-v1 integers.
4046:       JsonNode actual = C.parse(text);
4047:       long[] numeric = p3ReportNumericCounts(actual, 0);
4048:       phase = 3;
4049:       new com.citi.put.checks.studio.internal.StrictInternalBodyReader(JSON)
4050:           .read(bytes, com.citi.put.checks.studio.internal.dto.RunnerReport.class);
4051:       boolean finalReport = actual.path("kind").asText().equals("FINAL");
4052:       P3_CAPTURE_DIAGNOSTICS.compute(execution, (id, previous) -> {
4053:         ObjectNode metrics = previous == null ? C.object() : previous.deepCopy();
4054:         metrics.put("captureSuccesses", metrics.path("captureSuccesses").asLong() + 1);
4055:         if (finalReport) {
4056:           metrics.put("finalSuccesses", metrics.path("finalSuccesses").asLong() + 1)
4057:               .put("finalBytes", bytes.length).put("finalFloatLexemes", numeric[0])
4058:               .put("finalFractionalValues", numeric[1])
4059:               .put("guidedIntegerParserWouldRefuse", numeric[0] > 0);
4060:         }
4061:         return metrics;
4062:       });
4063:       if (finalReport) {
4064:         P3_FINAL_REPORTS.put(execution, actual);
4065:       }
4066:     } catch (Exception failure) {
4067:       final int failedPhase = phase;
4068:       P3_CAPTURE_DIAGNOSTICS.compute(execution, (id, previous) -> {
4069:         ObjectNode metrics = previous == null ? C.object() : previous.deepCopy();
4070:         return metrics.put("captureFailures", metrics.path("captureFailures").asLong() + 1)
4071:             .put("lastFailurePhase", failedPhase).put("lastFailureBytes", bytes.length);
4072:       });
4073:       // Metadata failure never changes the original controller response or creates a FINAL.
4074:     }
4075:   }
