4077:   private static long[] p3ReportNumericCounts(JsonNode node, int depth) {
4078:     if (depth > 64) {
4079:       throw new IllegalArgumentException("P3 callback witness depth");
4080:     }
4081:     long floats = 0, fractions = 0;
4082:     if (node.isNumber()) {
4083:       double number = node.doubleValue();
4084:       if (!Double.isFinite(number)) {
4085:         throw new IllegalArgumentException("P3 nonfinite callback number");
4086:       }
4087:       if (node.isFloatingPointNumber()) {
4088:         floats = 1;
4089:         fractions = number != Math.rint(number) ? 1 : 0;
4090:       }
4091:     }
4092:     if (node.isContainerNode()) {
4093:       for (JsonNode child : node) {
4094:         long[] counts = p3ReportNumericCounts(child, depth + 1);
4095:         floats += counts[0];
4096:         fractions += counts[1];
4097:       }
4098:     }
4099:     return new long[] {floats, fractions};
4100:   }
