4112:   private static Duration p3CleanupRequestTimeout(long deadline) {
4113:     long remaining = deadline - System.nanoTime();
4114:     if (remaining <= 0) {
4115:       throw new IllegalStateException("Actual ordinary cleanup deadline exhausted");
4116:     }
4117:     return Duration.ofNanos(Math.min(Duration.ofSeconds(15).toNanos(), remaining));
4118:   }
