4120:   private JsonNode p3CleanupSnapshot(UUID execution, String cookie, long deadline) throws Exception {
4121:     for (;;) {
4122:       long now = System.nanoTime();
4123:       long delay = Math.max(0, p3NextCleanupGetAt - now);
4124:       long remaining = deadline - now;
4125:       if (remaining <= delay) {
4126:         throw new IllegalStateException("Actual ordinary cleanup wait exceeds deadline");
4127:       }
4128:       if (delay > 0) {
4129:         java.util.concurrent.TimeUnit.NANOSECONDS.sleep(delay);
4130:       }
4131:       long requestStarted = System.nanoTime();
4132:       p3NextCleanupGetAt = requestStarted + Duration.ofSeconds(1).toNanos();
4133:       var request = HttpRequest.newBuilder(URI.create("https://localhost:" + port
4134:               + "/api/v1/studio/executions/" + execution))
4135:           .timeout(p3CleanupRequestTimeout(deadline)).header("Cookie", "put_session=" + cookie).GET().build();
4136:       var response = HttpClient.newBuilder().sslContext(TLS).build().send(request, HttpResponse.BodyHandlers.ofString());
4137:       if (response.statusCode() == 429) {
4138:         assertThat(C.parse(response.body()).path("error").path("code").asText()).isEqualTo("RATE_LIMITED");
4139:         String actualRetry = response.headers().firstValue("Retry-After")
4140:             .orElseThrow(() -> new IllegalStateException("Actual rate response lacks Retry-After"));
4141:         assertThat(actualRetry.matches("[1-9][0-9]{0,8}")).isTrue();
4142:         long seconds = Long.parseLong(actualRetry);
4143:         long retryNanos = Duration.ofSeconds(seconds).toNanos();
4144:         now = System.nanoTime();
4145:         if (retryNanos >= deadline - now) {
4146:           throw new IllegalStateException("Actual Retry-After exceeds cleanup deadline");
4147:         }
4148:         p3NextCleanupGetAt = Math.max(p3NextCleanupGetAt, now + retryNanos);
4149:         continue;
4150:       }
4151:       assertThat(response.statusCode()).as("actual bounded ordinary cleanup snapshot").isEqualTo(200);
4152:       if (System.nanoTime() >= deadline) {
4153:         throw new IllegalStateException("Actual cleanup response arrived past deadline");
4154:       }
4155:       return C.parse(response.body());
4156:     }
4157:   }
