4161:     long ordinaryDeadline = System.nanoTime() + Duration.ofSeconds(60).toNanos();
4162:     p3NextCleanupGetAt = System.nanoTime();
4163:     for (var owned : new java.util.ArrayList<>(p3OwnedOrdinaryCookies.entrySet())) {
4164:       try {
4165:         p3CleanupOrdinary(owned.getKey(), owned.getValue(), ordinaryDeadline);
4166:       } catch (Exception | AssertionError failure) {
4167:         failures.add(failure);
